-- ============================================================================
-- Repeatable seed: a demo catalogue for development.
--
-- Data is the DummyJSON open dataset (https://dummyjson.com), which exists for
-- exactly this: real product names, brands, descriptions, SKUs, stock levels,
-- photography and customer reviews, free to use in development. Nothing here
-- is scraped from a retailer, and nothing is invented.
--
-- REPEATABLE (R__), so Flyway re-applies it whenever this file changes rather
-- than recording a version that a later checkout would be missing. It is
-- idempotent: it clears what it previously inserted, then inserts again.
--
-- DEVELOPMENT ONLY. It reaches production the moment `classpath:db/seed` is on
-- spring.flyway.locations, so take that entry out before the first real
-- deployment. See application.properties.
-- ============================================================================

-- --------------------------------------------------------------- reset -----
-- Order matters: products hold a RESTRICT reference to categories, so the
-- products go first. Deleting a product cascades to its variants, images,
-- reviews and stock; deleting a deal cascades to its offers and their targets.
DELETE FROM deals WHERE slug IN ('flash-friday', 'daily-deals');
DELETE FROM products WHERE category_id IN (SELECT id FROM categories WHERE slug IN ('groceries', 'kitchen', 'mobile', 'sports', 'clothing', 'beauty', 'accessories', 'watches', 'home-living', 'footwear', 'automotive', 'computing'));
DELETE FROM categories WHERE slug IN ('groceries', 'kitchen', 'mobile', 'sports', 'clothing', 'beauty', 'accessories', 'watches', 'home-living', 'footwear', 'automotive', 'computing');
DELETE FROM users WHERE email LIKE '%@x.dummyjson.com';

-- ---------------------------------------------------------- categories -----

