-- ------------------------------------------------------------ variants -----
-- One default variant each: the dataset describes products, not size runs.
-- weight arrives in kilograms and is stored in grams.





-- -------------------------------------------------------------- images -----
-- Hotlinked from the dataset CDN. Swap these for your own storage before
-- launch: they are someone else's bandwidth and someone else's uptime.

















-- ----------------------------------------------------------- inventory -----
-- Real stock levels, so "in stock" is a fact about a quantity rather than a
-- flag somebody has to remember to flip.





-- --------------------------------------------------------------- deals -----
-- The dataset carries a discountPercentage per product. Rather than baking
-- it into the price, it becomes a real PERCENTAGE offer under a campaign —
-- which is what exercises the pricing model end to end.
                   starts_at, ends_at, priority, is_featured) VALUES
  ('ddf101b3-8baa-de63-ad73-5f40db9636bd', 'flash-friday', 'Flash Friday',
   'The eight deepest cuts in the shop. Until midnight.',
   'A short, loud campaign: limited allocation, and it ends on the clock.',
   'FLASH', 'ACTIVE', '-20%', now() - interval '2 hours', now() + interval '22 hours', 100, true),
  ('8481cccd-7cd5-6eea-516e-58cfcf969cb0', 'daily-deals', 'Deals of the Day',
   'Fresh reductions across every department.',
   'The everyday campaign the deals page browses.',
   'DAILY', 'ACTIVE', NULL, now() - interval '1 hour', now() + interval '13 hours', 10, false);







