INSERT INTO products (id, category_id, slug, name, description, brand, status) VALUES
  ('e5558fe4-7fa6-b9ff-542c-ddbc92962484', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'essence-mascara-lash-princess', 'Essence Mascara Lash Princess', 'The Essence Mascara Lash Princess is a popular mascara known for its volumizing and lengthening effects. Achieve dramatic lashes with this long-lasting and cruelty-free formula.', 'Essence', 'ACTIVE'),
  ('86cd71cc-b289-de5b-1d83-7adebb0c605f', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'eyeshadow-palette-with-mirror', 'Eyeshadow Palette with Mirror', 'The Eyeshadow Palette with Mirror offers a versatile range of eyeshadow shades for creating stunning eye looks. With a built-in mirror, it''s convenient for on-the-go makeup application.', 'Glamour Beauty', 'ACTIVE'),
  ('d3702ddd-741f-1981-fa5b-66516acc8458', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'powder-canister', 'Powder Canister', 'The Powder Canister is a finely milled setting powder designed to set makeup and control shine. With a lightweight and translucent formula, it provides a smooth and matte finish.', 'Velvet Touch', 'ACTIVE'),
  ('20647866-fd03-ab03-1b4d-10bb1d218e0b', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'red-lipstick', 'Red Lipstick', 'The Red Lipstick is a classic and bold choice for adding a pop of color to your lips. With a creamy and pigmented formula, it provides a vibrant and long-lasting finish.', 'Chic Cosmetics', 'ACTIVE'),
  ('cd4c69bc-8c62-fe10-dd1a-c46f9d9927bf', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'red-nail-polish', 'Red Nail Polish', 'The Red Nail Polish offers a rich and glossy red hue for vibrant and polished nails. With a quick-drying formula, it provides a salon-quality finish at home.', 'Nail Couture', 'ACTIVE'),
  ('81278afe-57cd-c51b-44d8-1f7bfc3508e0', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'calvin-klein-ck-one', 'Calvin Klein CK One', 'CK One by Calvin Klein is a classic unisex fragrance, known for its fresh and clean scent. It''s a versatile fragrance suitable for everyday wear.', 'Calvin Klein', 'ACTIVE'),
  ('2ca7fe66-d01b-933b-3cbb-f14af5cea30e', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'chanel-coco-noir-eau-de', 'Chanel Coco Noir Eau De', 'Coco Noir by Chanel is an elegant and mysterious fragrance, featuring notes of grapefruit, rose, and sandalwood. Perfect for evening occasions.', 'Chanel', 'ACTIVE'),
  ('b6debf70-5c7a-10ee-5de2-6aed676f7dfc', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'dior-j-adore', 'Dior J''adore', 'J''adore by Dior is a luxurious and floral fragrance, known for its blend of ylang-ylang, rose, and jasmine. It embodies femininity and sophistication.', 'Dior', 'ACTIVE'),
  ('75cb0429-cba2-c37c-050b-a0139d8e8471', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'dolce-shine-eau-de', 'Dolce Shine Eau de', 'Dolce Shine by Dolce & Gabbana is a vibrant and fruity fragrance, featuring notes of mango, jasmine, and blonde woods. It''s a joyful and youthful scent.', 'Dolce & Gabbana', 'ACTIVE'),
  ('1351dc47-483b-f6c4-ac1b-feeb7f603ec9', '7bf37f9e-2904-3fed-1095-a7609bd4af1f', 'gucci-bloom-eau-de', 'Gucci Bloom Eau de', 'Gucci Bloom by Gucci is a floral and captivating fragrance, with notes of tuberose, jasmine, and Rangoon creeper. It''s a modern and romantic scent.', 'Gucci', 'ACTIVE'),
  ('9589f739-e281-61ab-a5d8-cb46bff29e0a', '9568eb9c-b040-2a1f-7ebc-c8054c45bff0', 'annibale-colombo-bed', 'Annibale Colombo Bed', 'The Annibale Colombo Bed is a luxurious and elegant bed frame, crafted with high-quality materials for a comfortable and stylish bedroom.', 'Annibale Colombo', 'ACTIVE'),
  ('c37fdeb3-a4fb-ed8f-1b9c-3848ea9515b6', '9568eb9c-b040-2a1f-7ebc-c8054c45bff0', 'annibale-colombo-sofa', 'Annibale Colombo Sofa', 'The Annibale Colombo Sofa is a sophisticated and comfortable seating option, featuring exquisite design and premium upholstery for your living room.', 'Annibale Colombo', 'ACTIVE'),
  ('6835c826-3295-8cbd-1656-bc7e3906110d', '9568eb9c-b040-2a1f-7ebc-c8054c45bff0', 'bedside-table-african-cherry', 'Bedside Table African Cherry', 'The Bedside Table in African Cherry is a stylish and functional addition to your bedroom, providing convenient storage space and a touch of elegance.', 'Furniture Co.', 'ACTIVE'),
  ('ccc125e1-04ef-ec83-6450-4748a582115c', '9568eb9c-b040-2a1f-7ebc-c8054c45bff0', 'knoll-saarinen-executive-conference-chair', 'Knoll Saarinen Executive Conference Chair', 'The Knoll Saarinen Executive Conference Chair is a modern and ergonomic chair, perfect for your office or conference room with its timeless design.', 'Knoll', 'ACTIVE'),
  ('a42d38b0-95ff-2f66-cbef-bc94ddfd4cb8', '9568eb9c-b040-2a1f-7ebc-c8054c45bff0', 'wooden-bathroom-sink-with-mirror', 'Wooden Bathroom Sink With Mirror', 'The Wooden Bathroom Sink with Mirror is a unique and stylish addition to your bathroom, featuring a wooden sink countertop and a matching mirror.', 'Bath Trends', 'ACTIVE'),
  ('721464d6-8455-4a25-4731-09253ce91033', '9e4d4107-041f-3db8-1781-bed4219b6401', 'apple', 'Apple', 'Fresh and crisp apples, perfect for snacking or incorporating into various recipes.', NULL, 'ACTIVE'),
  ('a80ed131-7cba-9ecf-9513-eb846b8fbbeb', '9e4d4107-041f-3db8-1781-bed4219b6401', 'beef-steak', 'Beef Steak', 'High-quality beef steak, great for grilling or cooking to your preferred level of doneness.', NULL, 'ACTIVE'),
