  ('3734769d-0ed6-a7f3-4e49-0408dacc0087', '9e4d4107-041f-3db8-1781-bed4219b6401', 'green-bell-pepper', 'Green Bell Pepper', 'Fresh and vibrant green bell pepper, perfect for adding color and flavor to your dishes.', NULL, 'ACTIVE'),
