  ('c38e12b3-7564-b020-d112-b6a07d31d9d3', '9e4d4107-041f-3db8-1781-bed4219b6401', 'honey-jar', 'Honey Jar', 'Pure and natural honey in a convenient jar, perfect for sweetening beverages or drizzling over food.', NULL, 'ACTIVE'),
  ('15c0a1b3-a8d4-2a20-7f3c-2302c3d9895b', '9e4d4107-041f-3db8-1781-bed4219b6401', 'ice-cream', 'Ice Cream', 'Creamy and delicious ice cream, available in various flavors for a delightful treat.', NULL, 'ACTIVE'),
