  ('5e3ad546-2c10-d6a8-a7eb-45a6e084450a', '9e4d4107-041f-3db8-1781-bed4219b6401', 'red-onions', 'Red Onions', 'Flavorful and aromatic red onions, perfect for adding depth to your savory dishes.', NULL, 'ACTIVE'),
