  ('7dcdc205-e6cf-def7-5bec-9e7f04442bef', '51005366-6a28-6883-dce7-7ed916c346ae', 'blue-frock', 'Blue Frock', 'The Blue Frock is a charming and stylish dress for various occasions. With a vibrant blue color and a comfortable design, it adds a touch of elegance to your wardrobe.', NULL, 'ACTIVE'),
  ('eb1e4efa-539b-6ab9-db90-70176c7aaeaa', '51005366-6a28-6883-dce7-7ed916c346ae', 'girl-summer-dress', 'Girl Summer Dress', 'The Girl Summer Dress is a cute and breezy dress designed for warm weather. With playful patterns and lightweight fabric, it''s perfect for keeping cool and stylish during the summer.', NULL, 'ACTIVE'),
  ('7dfcf78e-31c5-7853-a464-a6ead40c9010', '51005366-6a28-6883-dce7-7ed916c346ae', 'gray-dress', 'Gray Dress', 'The Gray Dress is a versatile and chic option for various occasions. With a neutral gray color, it can be dressed up or down, making it a wardrobe staple for any fashion-forward individual.', NULL, 'ACTIVE'),
  ('2c6518a2-2661-f664-6895-839b0ea1df8e', '51005366-6a28-6883-dce7-7ed916c346ae', 'short-frock', 'Short Frock', 'The Short Frock is a playful and trendy dress with a shorter length. Ideal for casual outings or special occasions, it combines style and comfort for a fashionable look.', NULL, 'ACTIVE'),
  ('d1269a2d-ef12-303d-eca0-3d9923fd969d', '51005366-6a28-6883-dce7-7ed916c346ae', 'tartan-dress', 'Tartan Dress', 'The Tartan Dress features a classic tartan pattern, bringing a timeless and sophisticated touch to your wardrobe. Perfect for fall and winter, it adds a hint of traditional charm.', NULL, 'ACTIVE'),
  ('9f688c65-06ce-6135-cee2-51117c1ed6d5', 'ba886aff-d7a4-d9e6-606c-377fccdf894b', '300-touring', '300 Touring', 'The 300 Touring is a stylish and comfortable sedan, known for its luxurious features and smooth performance.', 'Chrysler', 'ACTIVE'),
  ('517b47a9-0589-1812-2402-5f628a481857', 'ba886aff-d7a4-d9e6-606c-377fccdf894b', 'charger-sxt-rwd', 'Charger SXT RWD', 'The Charger SXT RWD is a powerful and sporty rear-wheel-drive sedan, offering a blend of performance and practicality.', 'Dodge', 'ACTIVE'),
  ('940501ca-d4f5-b9cb-2cc0-ce8f967c4591', 'ba886aff-d7a4-d9e6-606c-377fccdf894b', 'dodge-hornet-gt-plus', 'Dodge Hornet GT Plus', 'The Dodge Hornet GT Plus is a compact and agile hatchback, perfect for urban driving with a touch of sportiness.', 'Dodge', 'ACTIVE'),
  ('1f661aed-dfce-8d4d-4a18-f3abc95b5955', 'ba886aff-d7a4-d9e6-606c-377fccdf894b', 'durango-sxt-rwd', 'Durango SXT RWD', 'The Durango SXT RWD is a spacious and versatile SUV, known for its strong performance and family-friendly features.', 'Dodge', 'ACTIVE'),
  ('60c78973-c53d-0b35-04bf-a7b2d5ac79cc', 'ba886aff-d7a4-d9e6-606c-377fccdf894b', 'pacifica-touring', 'Pacifica Touring', 'The Pacifica Touring is a stylish and well-equipped minivan, offering comfort and convenience for family journeys.', 'Chrysler', 'ACTIVE'),
  ('4ad06677-8ec1-9ad9-49b4-785055470682', '736fc949-1e11-2640-1427-b328273e56e6', 'blue-women-s-handbag', 'Blue Women''s Handbag', 'The Blue Women''s Handbag is a stylish and spacious accessory for everyday use. With a vibrant blue color and multiple compartments, it combines fashion and functionality.', 'Fashionista', 'ACTIVE'),
  ('b8480345-6887-b04f-334f-09fd58c20d46', '736fc949-1e11-2640-1427-b328273e56e6', 'heshe-women-s-leather-bag', 'Heshe Women''s Leather Bag', 'The Heshe Women''s Leather Bag is a luxurious and high-quality leather bag for the sophisticated woman. With a timeless design and durable craftsmanship, it''s a versatile accessory.', 'Heshe', 'ACTIVE'),
  ('aff18041-7dd5-341d-03d7-a473417869de', '736fc949-1e11-2640-1427-b328273e56e6', 'prada-women-bag', 'Prada Women Bag', 'The Prada Women Bag is an iconic designer bag that exudes elegance and luxury. Crafted with precision and featuring the Prada logo, it''s a statement piece for fashion enthusiasts.', 'Prada', 'ACTIVE'),
  ('cd93aeb4-0f6e-f98d-6c89-53d2a0628b58', '736fc949-1e11-2640-1427-b328273e56e6', 'white-faux-leather-backpack', 'White Faux Leather Backpack', 'The White Faux Leather Backpack is a trendy and practical backpack for the modern woman. With a sleek white design and ample storage space, it''s perfect for both casual and on-the-go styles.', 'Urban Chic', 'ACTIVE'),
  ('b31e1eae-c71d-6d0e-be97-44fecf6b138d', '736fc949-1e11-2640-1427-b328273e56e6', 'women-handbag-black', 'Women Handbag Black', 'The Women Handbag in Black is a classic and versatile accessory that complements various outfits. With a timeless black color and functional design, it''s a must-have in every woman''s wardrobe.', 'Elegance Collection', 'ACTIVE'),
  ('22024ff8-b4bf-ca4d-9492-c76b05af1da8', '51005366-6a28-6883-dce7-7ed916c346ae', 'black-women-s-gown', 'Black Women''s Gown', 'The Black Women''s Gown is an elegant and timeless evening gown. With a sleek black design, it''s perfect for formal events and special occasions, exuding sophistication and style.', NULL, 'ACTIVE'),
  ('ce05fcd8-f3d0-4048-dbcb-9fd318d7a30b', '51005366-6a28-6883-dce7-7ed916c346ae', 'corset-leather-with-skirt', 'Corset Leather With Skirt', 'The Corset Leather With Skirt is a bold and edgy ensemble that combines a stylish corset with a matching skirt. Ideal for fashion-forward individuals, it makes a statement at any event.', NULL, 'ACTIVE'),
  ('29dc32ab-0849-c9d1-b73f-743cf221713c', '51005366-6a28-6883-dce7-7ed916c346ae', 'corset-with-black-skirt', 'Corset With Black Skirt', 'The Corset With Black Skirt is a chic and versatile outfit that pairs a fashionable corset with a classic black skirt. It offers a trendy and coordinated look for various occasions.', NULL, 'ACTIVE'),
  ('ddaedef4-0af6-4f0f-8583-e04622a51bd2', '51005366-6a28-6883-dce7-7ed916c346ae', 'dress-pea', 'Dress Pea', 'The Dress Pea is a stylish and comfortable dress with a pea pattern. Perfect for casual outings, it adds a playful and fun element to your wardrobe, making it a great choice for day-to-day wear.', NULL, 'ACTIVE'),
  ('2371653c-9ad4-fc9a-1f92-bd5293b8e34e', '51005366-6a28-6883-dce7-7ed916c346ae', 'marni-red-black-suit', 'Marni Red & Black Suit', 'The Marni Red & Black Suit is a sophisticated and fashion-forward suit ensemble. With a combination of red and black tones, it showcases a modern design for a bold and confident look.', NULL, 'ACTIVE'),
  ('050dda73-7992-11ca-390c-91d9ddd9fcb2', '736fc949-1e11-2640-1427-b328273e56e6', 'green-crystal-earring', 'Green Crystal Earring', 'The Green Crystal Earring is a dazzling accessory that features a vibrant green crystal. With a classic design, it adds a touch of elegance to your ensemble, perfect for formal or special occasions.', NULL, 'ACTIVE'),
  ('a98aaabd-526c-6553-cd84-ae74aef177db', '736fc949-1e11-2640-1427-b328273e56e6', 'green-oval-earring', 'Green Oval Earring', 'The Green Oval Earring is a stylish and versatile accessory with a unique oval shape. Whether for casual or dressy occasions, its green hue and contemporary design make it a standout piece.', NULL, 'ACTIVE'),
  ('66437ec5-a37b-d0de-72c7-7709a1556bcc', '736fc949-1e11-2640-1427-b328273e56e6', 'tropical-earring', 'Tropical Earring', 'The Tropical Earring is a fun and playful accessory inspired by tropical elements. Featuring vibrant colors and a lively design, it''s perfect for adding a touch of summer to your look.', NULL, 'ACTIVE'),
  ('a72e44d7-d50e-e3d3-7e20-c8cfb1ad5f5b', 'dd6cc95c-bf5a-0da5-169f-e620d2abd0d9', 'black-brown-slipper', 'Black & Brown Slipper', 'The Black & Brown Slipper is a comfortable and stylish choice for casual wear. Featuring a blend of black and brown colors, it adds a touch of sophistication to your relaxation.', 'Comfort Trends', 'ACTIVE'),
  ('dd2eabe2-ce90-5ca9-344f-f2f33d21478d', 'dd6cc95c-bf5a-0da5-169f-e620d2abd0d9', 'calvin-klein-heel-shoes', 'Calvin Klein Heel Shoes', 'Calvin Klein Heel Shoes are elegant and sophisticated, designed for formal occasions. With a classic design and high-quality materials, they complement your stylish ensemble.', 'Calvin Klein', 'ACTIVE'),
  ('ef95e5b2-365d-b46a-30a3-22f990e980d9', 'dd6cc95c-bf5a-0da5-169f-e620d2abd0d9', 'golden-shoes-woman', 'Golden Shoes Woman', 'The Golden Shoes for Women are a glamorous choice for special occasions. Featuring a golden hue and stylish design, they add a touch of luxury to your outfit.', 'Fashion Diva', 'ACTIVE'),
  ('48ff693d-d4aa-1721-ccbd-139efb1cbe8b', 'dd6cc95c-bf5a-0da5-169f-e620d2abd0d9', 'pampi-shoes', 'Pampi Shoes', 'Pampi Shoes offer a blend of comfort and style for everyday use. With a versatile design, they are suitable for various casual occasions, providing a trendy and relaxed look.', 'Pampi', 'ACTIVE'),
  ('7698ab34-d9e2-aa06-2a07-b2ecabbb021d', 'dd6cc95c-bf5a-0da5-169f-e620d2abd0d9', 'red-shoes', 'Red Shoes', 'The Red Shoes make a bold statement with their vibrant red color. Whether for a party or a casual outing, these shoes add a pop of color and style to your wardrobe.', 'Fashion Express', 'ACTIVE'),
  ('652ed61e-2fb2-4a01-fcf5-f05cc13ae342', '0e2dd138-db86-0dc3-7ef2-02fae329690b', 'iwc-ingenieur-automatic-steel', 'IWC Ingenieur Automatic Steel', 'The IWC Ingenieur Automatic Steel watch is a durable and sophisticated timepiece. With a stainless steel case and automatic movement, it combines precision and style for watch enthusiasts.', 'IWC', 'ACTIVE'),
  ('eacc5e79-dad9-f468-26e0-c1dfcfe23c4f', '0e2dd138-db86-0dc3-7ef2-02fae329690b', 'rolex-cellini-moonphase-2', 'Rolex Cellini Moonphase', 'The Rolex Cellini Moonphase watch is a masterpiece of horology. Featuring a moon phase complication, it showcases the craftsmanship and elegance that Rolex is renowned for.', 'Rolex', 'ACTIVE'),
  ('6e28870e-1c1a-c0aa-0019-639091afb617', '0e2dd138-db86-0dc3-7ef2-02fae329690b', 'rolex-datejust-women', 'Rolex Datejust Women', 'The Rolex Datejust Women''s watch is an iconic timepiece designed for women. With a timeless design and a date complication, it offers both elegance and functionality.', 'Rolex', 'ACTIVE'),
  ('2161c19f-48f5-f869-52cc-648036d94fe5', '0e2dd138-db86-0dc3-7ef2-02fae329690b', 'watch-gold-for-women', 'Watch Gold for Women', 'The Gold Women''s Watch is a stunning accessory that combines luxury and style. Featuring a gold-plated case and a chic design, it adds a touch of glamour to any outfit.', 'Fashion Gold', 'ACTIVE'),
  ('5f7f2aed-1512-bb0f-cff3-38341a435c86', '0e2dd138-db86-0dc3-7ef2-02fae329690b', 'women-s-wrist-watch', 'Women''s Wrist Watch', 'The Women''s Wrist Watch is a versatile and fashionable timepiece for everyday wear. With a comfortable strap and a simple yet elegant design, it complements various styles.', 'Fashion Co.', 'ACTIVE');
